package run.ikaros.password; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/password/generator") public class PasswordGeneratorController{private final PasswordGeneratorService service;public PasswordGeneratorController(PasswordGeneratorService s){service=s;}@PostMapping("/password")public Mono<GeneratedSecretView> password(@Valid@RequestBody PasswordGenerateRequest r){return service.password(r);}@PostMapping("/passphrase")public Mono<GeneratedSecretView> passphrase(@Valid@RequestBody PassphraseGenerateRequest r){return service.passphrase(r);}}
